/* A story is one ordered journey. No HTML is generated by this view model. */
window.VacationJournal = {
  scenes(story) {
    return [
      { kind: 'opening', label: 'The beginning', title: story.title,
        text: story.opening.text, photo_url: story.chapters[0]?.photo_url,
        audio_url: story.opening.audio_url, audio_error: story.opening.audio_error },
      ...story.chapters.map((chapter, index) => ({ kind: 'moment', label: `Moment ${index + 1}`,
        title: chapter.title, text: chapter.narrative, photo_url: chapter.photo_url,
        photo_id: chapter.photo_id, location: chapter.location, time: chapter.time,
        audio_url: chapter.audio_url, audio_error: chapter.audio_error })),
      { kind: 'closing', label: 'Looking back', title: 'What stays with us',
        text: story.closing.text, audio_url: story.closing.audio_url,
        audio_error: story.closing.audio_error },
    ];
  },
};

/* Day-overview/moment-detail model. Coordinates are camera/user data only. */
window.VacationJourney = {
  model(story) {
    const moments = (story.moments || story.chapters || []).map((moment, index) => ({ ...moment, index }));
    const byId = new Map(moments.map(moment => [moment.photo_id, moment]));
    const days = (story.days || []).map((day, index) => ({ ...day, index, moments: day.moment_ids.map(id => byId.get(id)).filter(Boolean) }));
    const dayByMoment = new Map();
    days.forEach(day => day.moment_ids.forEach(id => dayByMoment.set(id, day.id)));
    const located = moments.filter(moment => typeof moment.latitude === 'number' && Number.isFinite(moment.latitude)
      && Math.abs(moment.latitude) <= 90 && typeof moment.longitude === 'number' && Number.isFinite(moment.longitude) && Math.abs(moment.longitude) <= 180);
    const route = located.slice(1).map((to, index) => ({ from: located[index], to,
      day_id: dayByMoment.get(to.photo_id), gap: to.index !== located[index].index + 1 }));
    return { moments, days, located, unlocated: moments.filter(moment => !located.includes(moment)), route, dayByMoment };
  },
};
